INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa799-85bc-7e8f-847b-a45e098e814a'::uuid, '019f9df7-a2a2-7930-a717-cd252273c91f'::uuid, 'Statistical diagrams and cumulative frequency curves', 'Frequency tables and diagrams organise data. A cumulative frequency curve gives median and quartiles by reading across and down.', ARRAY['Grouped frequency tables use class intervals; read inequality signs carefully when tallying', 'A cumulative frequency curve plots running total against the upper class boundary', 'Median at n/2; lower quartile at n/4; upper quartile at 3n/4 on the vertical axis']::text[], ARRAY['{"note":"n is the total frequency.","label":"Median position on CF curve","expression":"read across at n / 2"}'::jsonb, '{"note":"IQR = UQ - LQ.","label":"Quartile positions","expression":"LQ at n/4; UQ at 3n/4"}'::jsonb]::text[], ARRAY['{"steps":["For the median, read across from 100 on the CF axis to the curve, then down to the marks axis","For scores above 70, read up from 70 to find how many scored 70 or less","Number above 70 = 200 minus that reading"],"answer":"Median at CF = 100; number above 70 = 200 - CF reading at 70","question":"A cumulative frequency curve covers 200 students. Explain how to find the median and how many scored more than 70."}'::jsonb]::text[], ARRAY['{"fix":"Read at half the total frequency on the vertical (CF) axis.","mistake":"Reading the median halfway along the marks axis."}'::jsonb, '{"fix":"Plot against the upper class boundary.","mistake":"Plotting cumulative frequency against the class midpoint."}'::jsonb, '{"fix":"Check whether the interval uses < or <= before tallying.","mistake":"Misreading class inequalities when building a frequency table."}'::jsonb]::text[], ARRAY['Draw reading lines onto the graph to show your method.', 'Check the curve finishes at the total frequency.']::text[], ARRAY['t17']::text[], 1603, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T07:21:24.153Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa780-0e85-71c2-9e50-7ca09aa18fbc'::uuid, '019f9df7-a2a2-7941-9e48-3d4dda1f252c'::uuid, 'Probability of single and combined events', 'Probability is a fraction between 0 and 1. Tree diagrams and tables keep combined events organised.', ARRAY['All probabilities of an event and its complement add to 1', 'Multiply along the branches of a tree diagram, add between branches', 'Without replacement changes the denominator for the second pick']::text[], ARRAY['{"note":"Assumes all outcomes are equally likely.","label":"Single event","expression":"P(event) = favourable outcomes / total outcomes"}'::jsonb, '{"note":"Often much faster than counting directly.","label":"Complement","expression":"P(not A) = 1 - P(A)"}'::jsonb, '{"note":"Only when one does not affect the other.","label":"Independent events","expression":"P(A and B) = P(A) x P(B)"}'::jsonb]::text[], ARRAY['{"steps":["First counter red: 5/8","Now 4 red out of 7 remain, so second red: 4/7","Multiply along the branches: 5/8 x 4/7 = 20/56"],"answer":"5/14","question":"A bag has 5 red and 3 blue counters. Two are taken without replacement. Find the probability both are red."}'::jsonb]::text[], ARRAY['{"fix":"The total drops by one, and so does the count of that colour.","mistake":"Keeping the same denominator for the second pick without replacement."}'::jsonb, '{"fix":"Multiply along a branch. Only add between separate branches.","mistake":"Adding probabilities along a tree branch."}'::jsonb]::text[], ARRAY['Look for the phrase at least, it usually means use 1 minus the opposite.', 'Check every set of branch probabilities adds to 1.']::text[], ARRAY['t07']::text[], 1701, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:53:35.236Z'::timestamptz) ON CONFLICT (id) DO NOTHING;